// R6's family census (round 3): Messages, FaceTime, Contacts, Reminders and Calendar. Each app's rows are
//   - what its four-engine crawl found (census/<app>.crawled.mjs, generated by e2e/r6-rows-from-crawl.mjs), each driven
//     by a real-input probe of the generic runner (e2e/r6-app-census.mjs);
//   - the shared menu rows and shortcuts (r6-common commonRows) and its main window's chrome (chromeRows), verified by
//     r6-common's verifiers;
//   - one row per existing journey of the app, which runs first, in the same engine against the same server, and must
//     pass whole (Messages' includes the chaos run).
// An app's rows module tunes a crawled row by id where the crawl cannot say how to reach or check it.

import { appCensus } from "../r6-app-census.mjs";
import { chromeRows, commonRows } from "../r6-common.mjs";

/**
 * Each app: its name, its main window's region name, its Preferences window's region names, and its journeys.
 * `clockJourneys` drive the clock, so they run against `--clock-url`, a `ferrite dev --clock-ms` server of their own; the
 * others need time to pass by itself.
 */
export const APPS = {
  messages: {
    appName: "Messages",
    windowName: "Messages",
    prefs: "window",
    prefsWindow: /^(General|iMessage)$/,
    journeys: ["messages-journey.mjs", "messages-chaos.mjs", "messages-reasons-journey.mjs"],
  },
  facetime: {
    appName: "FaceTime",
    windowName: "FaceTime",
    prefs: "window",
    prefsWindow: /^(Settings|Blocked)$/,
    media: true,
    // FaceTime's menus (FaceTime File Edit Video Window Help) hold no full-screen command; its green button does it.
    fullScreenMenu: null,
    journeys: ["facetime-journey.mjs"],
  },
  contacts: {
    appName: "Contacts",
    windowName: "Contacts",
    prefs: "window",
    prefsWindow: /^(General|Accounts|Template|Phone|vCard)$/,
    journeys: ["contacts-journey.mjs"],
  },
  reminders: {
    appName: "Reminders",
    windowName: "Reminders",
    prefs: "window",
    prefsWindow: /^General$/,
    journeys: [
      "reminders-journey.mjs",
      "reminders-sharing-journey.mjs",
      "reminders-share-journey.mjs",
    ],
    clockJourneys: ["reminders-journey.mjs"],
  },
  calendar: {
    appName: "Calendar",
    windowName: "Calendar",
    prefs: "window",
    prefsWindow: /^(General|Accounts|Alerts|Advanced)$/,
    journeys: [
      "calendar-journey.mjs",
      "calendar-alerts-journey.mjs",
      "calendar-drag-journey.mjs",
      "calendar-ics-journey.mjs",
      "calendar-sync-journey.mjs",
    ],
  },
};

/** The census id of a journey file (the runner's own naming: `<app>.journey.<file without -journey.mjs>`). */
const journeyId = (app, file) => `${app}.journey.${file.replace(/(-journey)?\.mjs$/, "")}`;

/**
 * The app's rows: shared menu rows, the main window's chrome, a row per journey, and the crawled rows with `tune[id]`
 * applied (an object merged over the row; give `probe` whole to replace it, or `probe: null` with a `cell` to list the
 * control as unavailable, or with `journey` to map it to journey steps). `instanceOf: <id>` folds a crawled row that is
 * one instance of a data-driven kind (a seeded reminder, say) into that kind's pattern row, which verifies it.
 */
export function familyRows(app, crawled, tune = {}) {
  const spec = APPS[app];
  const journeys = spec.journeys.map((file) => ({
    id: journeyId(app, file),
    window: "flow",
    role: "flow",
    name: file,
    how: `node e2e/${file} --browser <engine> --url <server>, run first by the suite`,
    expected: "every step of the journey passes, with no console errors",
  }));
  const tuned = crawled
    .filter((row) => !tune[row.id]?.instanceOf)
    .map((row) => {
      const patch = tune[row.id];
      if (!patch) return row;
      const next = { ...row, ...patch };
      if (patch.probe === null) delete next.probe;
      return next;
    });
  const kinds = Object.values(tune)
    .map((patch) => patch.instanceOf)
    .filter(Boolean);
  const orphan = kinds.filter(
    (id) => !crawled.some((row) => row.id === id && !tune[id]?.instanceOf),
  );
  if (orphan.length)
    throw new Error(`instanceOf names rows that are not pattern rows: ${orphan.join(", ")}`);
  const unknown = Object.keys(tune).filter((id) => !crawled.some((row) => row.id === id));
  if (unknown.length)
    throw new Error(`tuning names rows the crawl does not have: ${unknown.join(", ")}`);
  return [
    ...commonRows(app, spec.appName, {
      prefs: spec.prefs,
      windowItem: spec.windowName,
      fullScreenMenu: spec.fullScreenMenu === undefined ? "View" : spec.fullScreenMenu,
      noEdit: spec.noEdit,
    }),
    ...chromeRows(app, "main", spec.windowName),
    ...journeys,
    ...tuned,
  ];
}

/** Run the app's census suite (`--phase`, `--browser` and the rest from the command line; see r6-kit options). */
export async function familyCensus(app, rows) {
  const spec = APPS[app];
  await appCensus({
    app,
    appName: spec.appName,
    windowName: spec.windowName,
    rows,
    media: spec.media ?? false,
    journeys: spec.journeys.map((file) => ({
      file,
      timeout: 900_000,
      clock: spec.clockJourneys?.includes(file) ?? false,
    })),
    chrome: [{ slug: "main", windowName: spec.windowName }],
    prefsWindow: spec.prefsWindow ?? null,
    windowItem: spec.windowName,
  });
}
